select     t.jgmc as jgmc,     t.zzl from (     select         oc.bmmc as jgmc,         round(             (               sum(case when left(db.tjzq, 4) = #{ssnd} then db.djsjje else 0 end) /               sum(case when left(db.tjzq, 4) = #{ssnd} - 1 then db.djsjje else 0 end) - 1             ) * 100,             2         ) as zzl     from dws_bus_per_paid_qfq db             join         ods_cszd_zdtm oc on db.ssjg = oc.zdbm and oc.zddm = 'JGDM'     where left(db.tjzq, 4) in (#{ssnd}, #{ssnd} - 1)             and case #{ssjd}                 when 1 then substring(db.tjzq, 5, 1) in (1, 2, 3)                 when 2 then substring(db.tjzq, 5, 1) in (4, 5, 6)                 when 3 then substring(db.tjzq, 5, 1) in (7, 8, 9)                 when 4 then substring(db.tjzq, 5, 2) in (10, 11, 12)             end     group by oc.bmmc ) as t where t.zzl > 4 
